  [/candle$/, (c) => (c.state?.lit === "true" ? 3 * Number(c.state?.candles ?? 1) : 0)],
  [/^sea_pickle$/, (c) => (c.state?.waterlogged === "false" ? 0 : 3 + 3 * Number(c.state?.pickles ?? 1))],
  [/^glow_lichen$/, 7],
